 T\'AU EMPIRE, SHADESTRAIN',32,0,''),('TAU','VESP','VESP',6,'WAR','Vespid Warrior','','kt24','6\"','2','0','0','5+','9','VESPID STINGWING, T\'AU EMPIRE, WARRIOR',32,0,''),('TYR','BBRO','BBRO',2,'AGIT','Brood Brother Agitator','','kt21','3[CIRCLE]','2','1','3','5+','7','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, AGITATOR',32,1,'Combat,Staunch'),('TYR','BBRO','BBRO',1,'CMDR','Brood Brother Commander','','kt21','3[CIRCLE]','2','1','3','5+','8','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, LEADER, COMMANDER',32,1,'Combat,Staunch,Marksman'),('TYR','BBRO','BBRO',3,'GNR','Brood Brother Gunner','','kt21','3[CIRCLE]','2','1','3','5+','7','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, AGITATOR',32,0,'Marksman'),('TYR','BBRO','BBRO',4,'ICNW','Brood Brother Iconward','','kt21','3[CIRCLE]','2','1','3','5+','7','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, ICONWARD',32,1,'Staunch'),('TYR','BBRO','BBRO',5,'KF','Brood Brother Knife Fighter','','kt21','3[CIRCLE]','2','1','3','5+','7','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, KNIFE FIGHTER',32,1,'Combat,Scout'),('TYR','BBRO','BBRO',13,'MAG','Magus','','kt21','3[CIRCLE]','3','1','3','4+','9','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODCOVEN, PSYKER, LEADER, MAGUS',32,1,'Combat,Staunch'),('TYR','BBRO','BBRO',6,'MDC','Brood Brother Medic','','kt21','3[CIRCLE]','2','1','3','5+','7','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODGUARD, MEDIC',32,1,'Staunch,Scout'),('TYR','BBRO','BBRO',15,'PAT','Patriarch','','kt21','3[CIRCLE]','4','1','3','4+','21','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODCOVEN, PSYKER, LEADER, PATRIARCH',32,1,'Combat,Staunch,Scout'),('TYR','BBRO','BBRO',12,'PF','Psychic Familiar','','kt21','3[CIRCLE]','2','2','2','5+','3','BROOD BROTHER, TYRANID, GENESTEALER CULT, PSYCHIC FAMILIAR',32,1,'Scout'),('TYR','BBRO','BBRO',14,'PRIM','Primus','','kt21','3[CIRCLE]','3','1','3','4+','9','BROOD BROTHER, TYRANID, GENESTEALER CULT, BROODCOVEN, PSYKER, LEADER, PRIMUS',32,1,